import json
import os

AHDEV_DIR = os.path.expanduser("~/.ahdev")
AHDEV_AUTH_FILE = os.path.join(AHDEV_DIR, "auth.json")
CODEX_AUTH_FILE = os.path.expanduser("~/.codex/auth.json")


def _load_autohome_token() -> str:
    try:
        with open(AHDEV_AUTH_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return (data.get("token") or data.get("api_key") or "").strip()
    except Exception:
        return ""


def ensure_codex_apikey_auth(token: str = "") -> bool:
    """确保 Codex auth.json 只保留 autohome API key，不保留 ChatGPT OAuth tokens。

    Codex/其他工具可能把 ~/.codex/auth.json 还原成 auth_mode=chatgpt + tokens。
    当 requires_openai_auth=true 时，Codex 可能优先用 tokens.access_token 发请求，
    导致请求没有使用 auto++ 下发的 autohome sk-key。hook 运行期做一次自愈。
    """
    api_key = (token or _load_autohome_token()).strip()
    if not api_key:
        return False

    desired = {"auth_mode": "apikey", "OPENAI_API_KEY": api_key}
    changed = True
    try:
        with open(CODEX_AUTH_FILE, "r", encoding="utf-8") as f:
            current = json.load(f)
        changed = (
            current.get("auth_mode") != "apikey" or
            current.get("OPENAI_API_KEY") != api_key or
            "tokens" in current or
            "last_refresh" in current
        )
    except Exception:
        changed = True

    if not changed:
        return False

    os.makedirs(os.path.dirname(CODEX_AUTH_FILE), exist_ok=True)
    with open(CODEX_AUTH_FILE, "w", encoding="utf-8") as f:
        json.dump(desired, f, ensure_ascii=False, indent=2)
    try:
        os.chmod(CODEX_AUTH_FILE, 0o600)
    except OSError:
        pass
    return True
